  page.route(re.compile(r'/src/lib/ipc\.ts(?:\?.*)?$'),fixture);page.goto(a.url,wait_until='networkidle');page.get_by_role('button',name='Use my saved phrases',exact=True).click();d=page.get_by_role('dialog',name='Your key layouts',exact=True);s=d.get_by_role('region',name='Use my saved phrases',exact=True)
  expect(s.get_by_text('Choose a saved layout above',exact=False)).to_be_visible();assert s.get_by_role('button').count()==0;assert page.evaluate('window.__phraseCopies.length')==0;checks.append('empty saved library offers configuration guidance without default/placeholder copying')
  d.get_by_role('button',name='Configure & save',exact=True).click();d.get_by_label('Layout name').fill('Desk replies');d.get_by_label('Action',exact=True).select_option('pasteTemplate');original='Thanks — 保存过😀\nKeep the condition.';d.get_by_label('Text to paste').fill(original);d.get_by_role('button',name='Save layout',exact=True).click();expect(d.get_by_role('status')).to_contain_text('Saved on this computer');d.get_by_role('button',name='Use my saved phrases',exact=True).click();expect(s.locator('.ol-saved-phrase-text')).to_have_text(original);s.get_by_role('button',name='Copy Key 1 · Single click',exact=True).click();expect(s.get_by_role('alert')).to_contain_text('Could not copy');expect(s.locator('.ol-saved-phrase-text')).to_have_text(original);checks.append('explicit copy failure leaves the actual saved Unicode/newline phrase intact for retry')
  page.evaluate('window.__copyFailure=false');s.get_by_role('button',name='Copy Key 1 · Single click',exact=True).click();expect(d.get_by_role('button',name='Close',exact=True)).to_be_disabled();expect(s.get_by_label('Saved layouts')).to_be_disabled();expect(d.get_by_role('button',name='Configure & save',exact=True)).to_be_disabled();d.press('Escape');expect(d).to_be_visible();page.evaluate('window.__finishCopy()');expect(s.get_by_role('status')).to_contain_text('Copied to your clipboard');expect(d.get_by_role('button',name='Close',exact=True)).to_be_enabled();assert page.evaluate('window.__phraseCopies.at(-1)')==original;checks.append('copy confirmation waits for the actual write promise; close/layout changes are held during copy instead of showing stale success')
  d.get_by_role('button',name='Configure & save',exact=True).click();d.get_by_label('Text to paste').fill('Unsaved replacement');d.get_by_role('button',name='Use my saved phrases',exact=True).click();expect(s.locator('.ol-saved-phrase-text')).to_have_text(original);s.get_by_role('button',name='Copy Key 1 · Single click',exact=True).click();assert page.evaluate('window.__phraseCopies.at(-1)')==original;page.evaluate('window.__finishCopy()');expect(s.get_by_role('status')).to_be_visible();d.get_by_role('button',name='Close',exact=True).click();expect(d.get_by_role('alert')).to_contain_text('unsaved');d.get_by_role('button',name='Keep editing',exact=True).click();d.get_by_role('button',name='Configure & save',exact=True).click();expect(d.get_by_label('Text to paste')).to_have_value('Unsaved replacement');d.get_by_role('button',name='Save layout',exact=True).click();expect(d.get_by_role('status')).to_contain_text('Saved on this computer');checks.append('reuse copies the saved revision while edits remain a protected independent draft; saving explicitly updates that revision')
  d.get_by_role('button',name=re.compile('^Key 3 ')).click();d.get_by_label('Press',exact=True).select_option('deviceCustomKeyDoubleClicks');d.get_by_label('Action',exact=True).select_option('pasteTemplate');d.get_by_label('Text to paste').fill('Double press reply');d.get_by_role('button',name='Save layout',exact=True).click();expect(d.get_by_role('status')).to_contain_text('Saved on this computer');d.get_by_role('button',name='Use my saved phrases',exact=True).click();expect(s.locator('.ol-saved-phrase-text')).to_have_count(2);expect(s.get_by_text('Unsaved replacement',exact=True)).to_be_visible();s.get_by_role('button',name='Copy Key 3 · Double click',exact=True).click();assert page.evaluate('window.__phraseCopies.at(-1)')=='Double press reply';page.evaluate('window.__finishCopy()');expect(s.get_by_role('status')).to_be_visible();checks.append('saved phrases are labelled with their actual key and gesture; another key copies its own text')
